77	impl InvokeBody {
78	  #[allow(dead_code)]
79	  pub(crate) fn into_json(self) -> JsonValue {
80	    match self {
81	      Self::Json(v) => v,
82	      Self::Raw(v) => {
83	        JsonValue::Array(v.into_iter().map(|n| JsonValue::Number(n.into())).collect())
84	      }
85	    }
86	  }
