98	pub fn map_lit<Map, Key, Value, TokenStreamKey, TokenStreamValue, FuncKey, FuncValue>(
99	  map_type: TokenStream,
100	  map: Map,
101	  map_key: FuncKey,
102	  map_value: FuncValue,
