132	/// Create a `serde_json::Value` variant `TokenStream` for a number
133	pub fn json_value_number_lit(num: &serde_json::Number) -> TokenStream {
134	  // See https://docs.rs/serde_json/1/serde_json/struct.Number.html for guarantees
135	  let prefix = quote! { ::serde_json::Value };
136	  if num.is_u64() {
137	    // guaranteed u64
138	    let num = num.as_u64().unwrap();
139	    quote! { #prefix::Number(#num.into()) }
140	  } else if num.is_i64() {
141	    // guaranteed i64
142	    let num = num.as_i64().unwrap();
143	    quote! { #prefix::Number(#num.into()) }
144	  } else if num.is_f64() {
145	    // guaranteed f64
146	    let num = num.as_f64().unwrap();
147	    quote! { #prefix::Number(::serde_json::Number::from_f64(#num).unwrap(/* safe to unwrap, guaranteed f64 */)) }
148	  } else {
149	    // invalid number
150	    quote! { #prefix::Null }
151	  }
152	}
