154	/// Create a `serde_json::Value` constructor `TokenStream`
155	pub fn json_value_lit(jv: &JsonValue) -> TokenStream {
156	  let prefix = quote! { ::serde_json::Value };
157	
158	  match jv {
159	    JsonValue::Null => quote! { #prefix::Null },
160	    JsonValue::Bool(bool) => quote! { #prefix::Bool(#bool) },
161	    JsonValue::Number(number) => json_value_number_lit(number),
162	    JsonValue::String(str) => {
163	      let s = str_lit(str);
164	      quote! { #prefix::String(#s) }
165	    }
166	    JsonValue::Array(vec) => {
167	      let items = vec.iter().map(json_value_lit);
168	      quote! { #prefix::Array(vec![#(#items),*]) }
169	    }
170	    JsonValue::Object(map) => {
