fn resolve_command(
  commands: &mut BTreeMap<String, Vec<ResolvedCommand>>,
  command: String,
  capability: &Capability,
  scope_id: Option<ScopeKey>,
  #[cfg(debug_assertions)] referenced_by_permission_identifier: String,
) -> Result<(), Error> {
  let mut contexts = Vec::new();
  if capability.local {
    contexts.push(ExecutionContext::Local);
  }
  if let Some(remote) = &capability.remote {
    contexts.extend(remote.urls.iter().map(|url| {
      ExecutionContext::Remote {
        url: Pattern::new(url)
          .unwrap_or_else(|e| panic!("invalid glob pattern for remote URL {url}: {e}")),
      }
    }));
  }

  let windows = parse_glob_patterns(capability.windows.iter().cloned().collect())?;
  let webviews = parse_glob_patterns(capability.webviews.iter().cloned().collect())?;

  for context in contexts {
    // each permission grant produces its own resolved entry, preserving its
    // scope and window constraints instead of being merged with other grants.
    commands
      .entry(command.clone())
      .or_default()
      .push(ResolvedCommand {
        #[cfg(debug_assertions)]
        referenced_by: vec![ResolvedCommandReference {
          capability: capability.identifier.clone(),
          permission: referenced_by_permission_identifier.clone(),
        }],
        context,
        windows: windows.clone(),
        webviews: webviews.clone(),
        scope_id,
      });
